// Find all notes containing the word "Flutter" in the title
Future<List<Note>> findNotesByTitle(String searchTerm) async {
  final isar = await isarService.db;
  return await isar.notes.filter()
      .titleContains(searchTerm, caseSensitive: false)
      .findAll();
}

content43.content:
Future<void> deleteNote(int noteId) async {
  final isar = await isarService.db;
  await isar.writeTxn(() async {
    final success = await isar.notes.delete(noteId);
    print(success ? 'Note deleted!' : 'Note not found.');
  });
}

